let number=0;
const lineGroups=paragraphs.map(lines=>lines.map((printedText,index)=>{
 const splitWord=printedText.endsWith('-');
 return {number:++number,printedText,text:splitWord?printedText.slice(0,-1):printedText,joinAfter:splitWord||index===lines.length-1?'':' '};
}));

export const readingPassage={
 title:'Going Home',
 attribution:'PROSE FICTION: This passage is adapted from the short story “Going Home” by Lucretia Prynne (©2007 by Lucretia Prynne).',
 source:'The text, printed line breaks, numbering, and answer key follow the supplied screenshots. On a phone the text reflows for reading; evidence references retain the original line numbers.',
 sourceLines:lineGroups.flat(),
 lineRanges:lineGroups.map(lines=>({from:lines[0].number,to:lines.at(-1).number})),
 paragraphs:lineGroups.map(lines=>lines.map(line=>line.text+line.joinAfter).join('')),
};
